import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';

const API_URL = 'http://localhost:5000/api';

const DatasetsPage = () => {
  const { isAdmin } = useAuth();
  const [datasets, setDatasets] = useState([]);
  const [workshops, setWorkshops] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  
  // Состояние для создания нового датасета
  const [isCreating, setIsCreating] = useState(false);
  const [newDataset, setNewDataset] = useState({
    name: '',
    M: 3,
    N: 3,
    workshop: null,
    matrix: Array(3).fill().map(() => Array(3).fill(0))
  });
  
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        
        // Получаем список датасетов
        const datasetsResponse = await axios.get(`${API_URL}/datasets`);
        setDatasets(datasetsResponse.data);
        
        // Получаем список цехов
        const workshopsResponse = await axios.get(`${API_URL}/workshops`);
        setWorkshops(workshopsResponse.data);
        
        setError('');
      } catch (error) {
        console.error('Ошибка при загрузке данных:', error);
        setError('Произошла ошибка при загрузке данных');
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, []);
  
  const handleCreateDataset = async () => {
    try {
      // Проверка имени
      if (!newDataset.name.trim()) {
        setError('Имя датасета не может быть пустым');
        return;
      }
      
      // Проверка размеров матрицы
      if (newDataset.M < 1 || newDataset.N < 1) {
        setError('Размеры матрицы должны быть положительными числами');
        return;
      }
      
      setLoading(true);
      
      // Отправка запроса на создание датасета
      await axios.post(`${API_URL}/datasets`, newDataset);
      
      // Получаем обновленный список датасетов
      const datasetsResponse = await axios.get(`${API_URL}/datasets`);
      setDatasets(datasetsResponse.data);
      
      // Сброс формы
      setNewDataset({
        name: '',
        M: 3,
        N: 3,
        workshop: null,
        matrix: Array(3).fill().map(() => Array(3).fill(0))
      });
      
      setIsCreating(false);
      setError('');
    } catch (error) {
      console.error('Ошибка при создании датасета:', error);
      setError('Произошла ошибка при создании датасета');
    } finally {
      setLoading(false);
    }
  };
  
  const handleDeleteDataset = async (id) => {
    if (!window.confirm('Вы действительно хотите удалить этот датасет?')) {
      return;
    }
    
    try {
      setLoading(true);
      
      // Отправка запроса на удаление датасета
      await axios.delete(`${API_URL}/datasets/${id}`);
      
      // Получаем обновленный список датасетов
      const datasetsResponse = await axios.get(`${API_URL}/datasets`);
      setDatasets(datasetsResponse.data);
      
      setError('');
    } catch (error) {
      console.error('Ошибка при удалении датасета:', error);
      setError('Произошла ошибка при удалении датасета');
    } finally {
      setLoading(false);
    }
  };
  
  const handleMatrixChange = (rowIndex, colIndex, value) => {
    const newMatrix = [...newDataset.matrix];
    newMatrix[rowIndex][colIndex] = parseInt(value) || 0;
    setNewDataset({ ...newDataset, matrix: newMatrix });
  };
  
  const handleMatrixSizeChange = () => {
    // Создаем новую матрицу с новыми размерами
    const newMatrix = Array(parseInt(newDataset.M) || 1)
      .fill()
      .map((_, i) => 
        Array(parseInt(newDataset.N) || 1)
          .fill()
          .map((_, j) => {
            // Пытаемся сохранить существующие значения
            if (i < newDataset.matrix.length && j < newDataset.matrix[0]?.length) {
              return newDataset.matrix[i][j];
            }
            return 0;
          })
      );
    
    setNewDataset({ ...newDataset, matrix: newMatrix });
  };
  
  if (loading && !isCreating) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="text-lg text-gray-500">Загрузка...</div>
      </div>
    );
  }
  
  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-800">Датасеты</h1>
        
        {isAdmin && !isCreating && (
          <button
            onClick={() => setIsCreating(true)}
            className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
          >
            Создать датасет
          </button>
        )}
      </div>
      
      {error && (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">
          {error}
        </div>
      )}
      
      {isCreating && (
        <div className="bg-white shadow rounded-lg p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">Создание нового датасета</h2>
          
          <div className="space-y-4">
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-gray-700">
                Название
              </label>
              <input
                type="text"
                id="name"
                value={newDataset.name}
                onChange={(e) => setNewDataset({ ...newDataset, name: e.target.value })}
                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
            
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="rows" className="block text-sm font-medium text-gray-700">
                  Количество строк (M)
                </label>
                <input
                  type="number"
                  id="rows"
                  min="1"
                  value={newDataset.M}
                  onChange={(e) => setNewDataset({ ...newDataset, M: parseInt(e.target.value) || 1 })}
                  onBlur={handleMatrixSizeChange}
                  className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                />
              </div>
              
              <div>
                <label htmlFor="cols" className="block text-sm font-medium text-gray-700">
                  Количество столбцов (N)
                </label>
                <input
                  type="number"
                  id="cols"
                  min="1"
                  value={newDataset.N}
                  onChange={(e) => setNewDataset({ ...newDataset, N: parseInt(e.target.value) || 1 })}
                  onBlur={handleMatrixSizeChange}
                  className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                />
              </div>
            </div>
            
            <div>
              <label htmlFor="workshop" className="block text-sm font-medium text-gray-700">
                Цех (необязательно)
              </label>
              <select
                id="workshop"
                value={newDataset.workshop || ''}
                onChange={(e) => setNewDataset({ 
                  ...newDataset, 
                  workshop: e.target.value === '' ? null : parseInt(e.target.value)
                })}
                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
              >
                <option value="">Не выбрано</option>
                {workshops.map(workshop => (
                  <option key={workshop.id} value={workshop.id}>
                    {workshop.name || `Цех #${workshop.id}`}
                  </option>
                ))}
              </select>
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Матрица данных
              </label>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200 border">
                  <tbody className="bg-white divide-y divide-gray-200">
                    {newDataset.matrix.map((row, rowIndex) => (
                      <tr key={rowIndex}>
                        {row.map((cell, colIndex) => (
                          <td key={colIndex} className="px-2 py-2 whitespace-nowrap border">
                            <input
                              type="number"
                              value={cell}
                              onChange={(e) => handleMatrixChange(rowIndex, colIndex, e.target.value)}
                              className="block w-full border-0 p-1 focus:outline-none focus:ring-0 text-center"
                              style={{ width: '60px' }}
                            />
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
            
            <div className="flex justify-end space-x-3">
              <button
                onClick={() => setIsCreating(false)}
                className="px-4 py-2 border border-gray-300 text-gray-700 rounded-md hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
              >
                Отмена
              </button>
              
              <button
                onClick={handleCreateDataset}
                disabled={loading}
                className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
              >
                {loading ? 'Сохранение...' : 'Сохранить датасет'}
              </button>
            </div>
          </div>
        </div>
      )}
      
      {datasets.length === 0 ? (
        <div className="bg-white shadow rounded-lg p-6 text-center">
          <p className="text-gray-500">Нет доступных датасетов</p>
        </div>
      ) : (
        <div className="bg-white shadow rounded-lg overflow-hidden">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  ID
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Название
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Размер
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Цех
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Действия
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {datasets.map(dataset => (
                <tr key={dataset.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    {dataset.id}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                    {dataset.name || `Датасет #${dataset.id}`}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {dataset.M && dataset.N ? `${dataset.M}x${dataset.N}` : 'Не указан'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {dataset.workshop ? (
                      workshops.find(w => w.id === dataset.workshop)?.name || `Цех #${dataset.workshop}`
                    ) : (
                      'Не назначен'
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <Link
                      to={`/datasets/${dataset.id}`}
                      className="text-indigo-600 hover:text-indigo-900 mr-4"
                    >
                      Просмотр
                    </Link>
                    
                    {isAdmin && (
                      <button
                        onClick={() => handleDeleteDataset(dataset.id)}
                        className="text-red-600 hover:text-red-900"
                      >
                        Удалить
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default DatasetsPage;
